// n8n Code node: "Select leads" (Run Once for All Items)
// Turns raw Google Places rows into a clean, de-duplicated list of leads.

const BLOCKED_HOSTS = [
  'facebook.com', 'instagram.com', 'linkedin.com', 'twitter.com', 'x.com',
  'youtube.com', 'tiktok.com', 'yelp.com', 'justdial.com', 'tripadvisor.com',
  'linktr.ee', 'wa.me', 'google.com', 'goo.gl', 'maps.app.goo.gl',
  // social / aggregator / directory profiles that are not the business's own site
  'foursquare.com', 'yellowpages.com', 'thumbtack.com', 'angi.com', 'angieslist.com',
  'bbb.org', 'trustpilot.com', 'nextdoor.com', 'bark.com', 'alignable.com',
];
const MAX_LEADS = 100;

function hostOf(raw) {
  if (!raw || typeof raw !== 'string') return null;
  try {
    const u = new URL(/^https?:\/\//i.test(raw.trim()) ? raw.trim() : 'https://' + raw.trim());
    return u.hostname.replace(/^www\./, '').toLowerCase() || null;
  } catch {
    return null;
  }
}

function isBlocked(host) {
  return BLOCKED_HOSTS.some((b) => host === b || host.endsWith('.' + b));
}

function selectLeads(places, { limit, knownDomains = [], maxPerRun = MAX_LEADS }) {
  const cap = Math.max(1, Math.min(Number(limit) || 10, MAX_LEADS, Number(maxPerRun) || MAX_LEADS));
  const seen = new Set(knownDomains.map((d) => String(d).toLowerCase()));
  const leads = [];
  for (const p of places) {
    if (leads.length >= cap) break;
    if (!p || p.permanentlyClosed || p.temporarilyClosed) continue;
    const host = hostOf(p.website);
    if (!host || isBlocked(host) || seen.has(host)) continue;
    seen.add(host);
    leads.push({
      name: String(p.title || host).trim(),
      domain: host,
      website: 'https://' + host,
      category: p.categoryName || '',
      address: p.address || '',
      phone: p.phone || '',
      rating: p.totalScore ?? '',
      reviews: p.reviewsCount ?? '',
    });
  }
  return leads;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { selectLeads, hostOf, isBlocked, MAX_LEADS };
}
if (typeof $input !== 'undefined') {
  const form = $('On form submission').first().json;
  const places = $('Google Places').all().map((i) => i.json);
  const knownDomains = $('Read lead log').all().map((i) => i.json.Domain).filter(Boolean);
  const cfg = $('Config').first().json;
  // In send mode, cap the batch so one run can't blast past the sender's daily limit.
  const maxPerRun = form['Mode'] === 'Send now' ? cfg.maxSendsPerRun : MAX_LEADS;
  return selectLeads(places, { limit: form['Lead Number'], knownDomains, maxPerRun }).map((json) => ({ json }));
}

// n8n Code node: "Find contact page" (Run Once for Each Item)
// Looks through the homepage HTML for a contact-ish link on the same site.

function findContactUrl(html, origin) {
  const base = new URL(origin);
  const anchor = /<a\s[^>]*?href\s*=\s*["']([^"'#]+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  const wanted = /contact|get[\s-]?in[\s-]?touch|reach[\s-]?us|enquir|inquir/i;
  let m;
  while ((m = anchor.exec(html || ''))) {
    const [, href, inner] = m;
    if (/^(mailto|tel|javascript):/i.test(href)) continue;
    if (!wanted.test(href) && !wanted.test(inner.replace(/<[^>]+>/g, ' '))) continue;
    try {
      const u = new URL(href, base);
      if (u.hostname.replace(/^www\./, '') === base.hostname.replace(/^www\./, '')) return u.href;
    } catch { /* ignore malformed href */ }
  }
  return new URL('/contact', base).href; // blind guess; a 404 is harmless
}

if (typeof module !== 'undefined' && module.exports) module.exports = { findContactUrl };
if (typeof $input !== 'undefined') {
  const lead = $('Each lead').item.json;
  const html = typeof $json.data === 'string' ? $json.data : '';
  return { json: { contactUrl: findContactUrl(html, lead.website) } };
}

// n8n Code node: "Pick email" (Run Once for Each Item)
// Pulls every email-looking string out of the fetched pages and picks the best one.
// Deterministic on purpose: an LLM that is only handed a URL cannot read the page.

const EMAIL_RE = /[a-z0-9._%+-]+@[a-z0-9-]+(?:\.[a-z0-9-]+)*\.[a-z]{2,}/gi;
const FILE_TLDS = new Set(['png', 'jpg', 'jpeg', 'gif', 'svg', 'webp', 'avif', 'css', 'js', 'woff', 'woff2', 'ico']);
const JUNK_LOCAL = /^(no-?reply|do-?not-?reply|donotreply|mailer-daemon|postmaster|abuse|webmaster|privacy|example|user|name|email|your-?email|test)$/i;
const JUNK_DOMAINS = new Set(['sentry.io', 'wixpress.com', 'example.com', 'domain.com', 'yourdomain.com', 'email.com', 'sentry-next.wixpress.com']);
const PREFERRED = ['info', 'contact', 'hello', 'sales', 'enquiries', 'enquiry', 'office', 'support', 'admin', 'team', 'hi'];

// Cloudflare "email protection": data-cfemail="<hex>", first byte is the XOR key.
function decodeCf(hex) {
  try {
    const key = parseInt(hex.slice(0, 2), 16);
    let out = '';
    for (let i = 2; i < hex.length; i += 2) out += String.fromCharCode(parseInt(hex.slice(i, i + 2), 16) ^ key);
    return out;
  } catch {
    return '';
  }
}

function candidates(html) {
  const text = String(html || '');
  const found = new Map(); // email -> viaMailto
  const add = (e, mailto) => {
    const email = e.toLowerCase().replace(/^[^a-z0-9]+|[.]+$/g, '');
    if (!email.includes('@')) return;
    found.set(email, found.get(email) || mailto);
  };
  for (const m of text.matchAll(/mailto:([^"'?\s>]+)/gi)) {
    let v = m[1];
    try { v = decodeURIComponent(v); } catch { /* keep raw */ }
    add(v, true);
  }
  for (const m of text.matchAll(/data-cfemail=["']([0-9a-f]+)["']/gi)) add(decodeCf(m[1]), true);
  const plain = text
    .replace(/\s*[\[(]\s*at\s*[\])]\s*/gi, '@')
    .replace(/\s*[\[(]\s*dot\s*[\])]\s*/gi, '.');
  for (const m of plain.matchAll(EMAIL_RE)) add(m[0], false);
  return found;
}

function isUsable(email) {
  const [local, domain] = email.split('@');
  if (!local || !domain) return false;
  if (JUNK_LOCAL.test(local) || JUNK_DOMAINS.has(domain)) return false;
  if (FILE_TLDS.has(domain.split('.').pop())) return false;
  if (/^\d+x$/.test(domain.split('.')[0]) || local.length > 64) return false;
  return true;
}

function score(email, viaMailto, siteDomain) {
  const [local, domain] = email.split('@');
  let s = 0;
  if (domain === siteDomain || domain.endsWith('.' + siteDomain)) s += 10;
  const i = PREFERRED.indexOf(local);
  if (i >= 0) s += 8 - i * 0.5;
  if (viaMailto) s += 2;
  return s;
}

function pickEmail(pages, siteDomain) {
  const all = new Map();
  for (const html of pages) for (const [e, mailto] of candidates(html)) all.set(e, all.get(e) || mailto);
  const ranked = [...all.entries()]
    .filter(([e]) => isUsable(e))
    .map(([e, mailto]) => ({ email: e, score: score(e, mailto, siteDomain) }))
    .sort((a, b) => b.score - a.score || a.email.localeCompare(b.email));
  // Only trust addresses on the company's own domain, or a mailbox it published via mailto.
  const best = ranked.find((r) => r.score >= 10 || all.get(r.email));
  return { email: best ? best.email : '', alternatives: ranked.slice(0, 5).map((r) => r.email) };
}

if (typeof module !== 'undefined' && module.exports) module.exports = { pickEmail, candidates, isUsable, decodeCf };
if (typeof $input !== 'undefined') {
  const lead = $('Each lead').item.json;
  const home = $('Fetch homepage').item.json.data;
  const contact = $json.data;
  const { email, alternatives } = pickEmail([home, contact], lead.domain);
  return { json: { ...lead, email, alternatives: alternatives.join(', ') } };
}

// n8n Code node: "Summarize site" (Run Once for Each Item)
// Boils the homepage down to a few facts the drafting model can safely reference.

const decode = (s) => s
  .replace(/&amp;/g, '&').replace(/&#0?39;|&apos;/g, "'").replace(/&quot;/g, '"')
  .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
const clean = (s) => decode(String(s || '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();

function summarizeSite(html) {
  const src = String(html || '').replace(/<(script|style|noscript|svg)[\s\S]*?<\/\1>/gi, ' ');
  const title = clean((src.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1]);
  const metaTag = src.match(/<meta[^>]+(?:name|property)=["'](?:og:)?description["'][^>]*>/i);
  const description = metaTag ? clean((metaTag[0].match(/content=["']([^"']*)["']/i) || [])[1]) : '';
  const headings = [...src.matchAll(/<h[12][^>]*>([\s\S]*?)<\/h[12]>/gi)]
    .map((m) => clean(m[1])).filter((h) => h.length > 3 && h.length < 120).slice(0, 4);
  const parts = [title && `Title: ${title.slice(0, 120)}`, description && `Description: ${description.slice(0, 240)}`,
    headings.length && `Headings: ${headings.join(' | ')}`].filter(Boolean);
  return parts.join('\n');
}

if (typeof module !== 'undefined' && module.exports) module.exports = { summarizeSite };
if (typeof $input !== 'undefined') {
  return { json: { ...$json, siteSummary: summarizeSite($('Fetch homepage').item.json.data) } };
}

// n8n Code node: "Verify email" (Run Once for Each Item)
// Reads the DNS-over-HTTPS MX answer for the email's domain. Fails closed only on a definite "no mail server".

const SYNTAX = /^[a-z0-9._%+-]+@[a-z0-9-]+(?:\.[a-z0-9-]+)*\.[a-z]{2,}$/i;

function mxVerdict(email, dns) {
  if (!SYNTAX.test(email || '')) return { ok: false, status: 'bad_email' };
  if (!dns || dns.error || typeof dns.Status !== 'number') return { ok: true, status: 'mx_unchecked' }; // lookup failed: don't punish the lead
  if (dns.Status === 3) return { ok: false, status: 'no_mx' }; // NXDOMAIN
  const mx = (dns.Answer || []).filter((a) => a.type === 15 && !/^\d+\s+\.?$/.test(String(a.data).trim()));
  if (dns.Status === 0 && mx.length === 0) return { ok: false, status: 'no_mx' };
  return { ok: true, status: 'mx_ok' };
}

if (typeof module !== 'undefined' && module.exports) module.exports = { mxVerdict };
if (typeof $input !== 'undefined') {
  const lead = $('Summarize site').item.json;
  const v = mxVerdict(lead.email, $json);
  return { json: { ...lead, emailOk: v.ok, status: v.ok ? '' : v.status, emailCheck: v.status } };
}

// n8n Code node: "Build prompt" (Run Once for Each Item)
// Builds the OpenRouter chat request. Style and offer come from the form, so nothing is niche-specific.

const STYLES = {
  Friendly: 'Warm and conversational. Contractions are fine. Sounds like a helpful peer, not a salesperson.',
  Professional: 'Polished and concise. Formal but not stiff. No slang, no exclamation marks.',
  Simple: 'Very plain. Three or four short sentences. No adjectives you could delete.',
};

function buildRequest({ lead, offer, style, senderName, senderCompany, model }) {
  const system = [
    'You write short cold outreach emails on behalf of a real sender.',
    `Tone: ${STYLES[style] || STYLES.Professional}`,
    'Rules:',
    '- Body is at most 110 words, plain text, no markdown, no emojis.',
    '- If "Site says" facts are given, you may reference ONE of them naturally (in your own words, not quoted); skip it if none is clearly useful.',
    '- Use ONLY the facts provided about the recipient. Never claim to have followed, used, or studied their business, and never praise their "impressive work".',
    '- Start with "Hi <company name> team,".',
    '- State what the sender offers in one concrete sentence tied to the recipient\'s category.',
    '- End with one low-pressure question as the call to action.',
    '- Do not include a signature, placeholders, or links; they are added separately.',
    '- Subject under 60 characters, no clickbait, no all-caps.',
    'Respond with JSON only: {"subject": string, "body": string}.',
  ].join('\n');
  const facts = [
    `Recipient company: ${lead.name}`,
    lead.category && `Category: ${lead.category}`,
    lead.address && `Location: ${lead.address}`,
    lead.rating && `Public Google rating: ${lead.rating} (${lead.reviews || 'n/a'} reviews)`,
    `Website: ${lead.website}`,
    lead.siteSummary && `Site says:\n${lead.siteSummary}`,
  ].filter(Boolean).join('\n');
  const user = `${facts}\n\nSender: ${senderName}, ${senderCompany}\nWhat the sender offers: ${offer}`;
  return {
    model,
    temperature: 0.7,
    max_tokens: 400,
    response_format: { type: 'json_object' },
    messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  };
}

if (typeof module !== 'undefined' && module.exports) module.exports = { buildRequest, STYLES };
if (typeof $input !== 'undefined') {
  const form = $('On form submission').first().json;
  const cfg = $('Config').first().json;
  const lead = $json;
  return {
    json: {
      lead,
      request: buildRequest({
        lead,
        offer: form['What you offer'],
        style: form['Email Style'],
        senderName: cfg.senderName,
        senderCompany: cfg.senderCompany,
        model: cfg.model,
      }),
    },
  };
}

// n8n Code node: "Parse draft" (Run Once for Each Item)
// Validates the model's JSON, falls back to a template if the call failed, then adds signature + opt-out footer.

// Every opener starts the same way, so fallback and model drafts read alike.
const FALLBACK_OPENERS = {
  Friendly: (c) => `Hi ${c} team,\n\nThanks for taking a minute to read this.`,
  Professional: (c) => `Hi ${c} team,\n\nI am reaching out briefly.`,
  Simple: (c) => `Hi ${c} team,`,
};

function extractJson(content) {
  if (typeof content !== 'string') return null;
  const cleaned = content.replace(/^```(?:json)?\s*|\s*```$/g, '').trim();
  try {
    const obj = JSON.parse(cleaned);
    const subject = typeof obj.subject === 'string' ? obj.subject.trim() : '';
    const body = typeof obj.body === 'string' ? obj.body.trim() : '';
    if (subject && body && body.length < 1500) return { subject, body };
  } catch { /* fall through */ }
  return null;
}

function fallbackDraft({ lead, offer, style }) {
  const open = (FALLBACK_OPENERS[style] || FALLBACK_OPENERS.Professional)(lead.name);
  return {
    subject: `Quick idea for ${lead.name}`.slice(0, 60),
    body: `${open}\n\nWe help ${lead.category ? lead.category.toLowerCase() + ' businesses' : 'businesses like yours'} with the following: ${offer}\n\nWould it be useful if I sent over a short example?`,
  };
}

function finalize(draft, { senderName, senderCompany, calendarLink, postalAddress }) {
  const parts = [draft.body.trim(), ''];
  if (calendarLink) parts.push(`If easier, grab a time here: ${calendarLink}`, '');
  parts.push('Best,', senderName, senderCompany, '');
  parts.push("If you'd rather not hear from me, reply 'no thanks' and I won't email you again.");
  if (postalAddress) parts.push(postalAddress);
  return { subject: draft.subject, body: parts.join('\n') };
}

function parseDraft({ content, lead, offer, style, cfg }) {
  const parsed = extractJson(content);
  const draft = parsed || fallbackDraft({ lead, offer, style });
  return { ...finalize(draft, cfg), draftSource: parsed ? 'llm' : 'fallback' };
}

if (typeof module !== 'undefined' && module.exports) module.exports = { parseDraft, extractJson, fallbackDraft, finalize };
if (typeof $input !== 'undefined') {
  const form = $('On form submission').first().json;
  const cfg = $('Config').first().json;
  const { lead } = $('Build prompt').item.json;
  const content = $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content;
  const out = parseDraft({ content, lead, offer: form['What you offer'], style: form['Email Style'], cfg });
  return { json: { ...lead, ...out } };
}
